const TAG=encodeURIComponent(new URL('./',self.location.href).pathname),CORE='italia-gh-core-v5-'+TAG,AUDIO='italia-gh-audio-v1-'+TAG,IMAGES='italia-gh-images-v1-'+TAG;
const FILES=['./','./index.html','./style.css?v=offline-v5','./app.js?v=offline-v5','./image-manifest.js?v=offline-v5','./data.js?v=public-v1','./audio-manifest.js?v=public-v1','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',e=>e.waitUntil((async()=>{const c=await caches.open(CORE);await c.addAll(FILES);await self.skipWaiting()})()));
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
async function partial(request,response){const range=request.headers.get('range');if(!range)return response;const data=await response.arrayBuffer(),size=data.byteLength;const match=/^bytes=(\d*)-(\d*)$/.exec(range);if(!match)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${size}`}});let start=match[1]?+match[1]:Math.max(0,size-(+match[2]||0));let end=match[1]?(match[2]?Math.min(+match[2],size-1):size-1):size-1;if(start>=size||start>end)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${size}`}});return new Response(data.slice(start,end+1),{status:206,headers:{'Content-Type':response.headers.get('content-type')||'audio/mpeg','Content-Range':`bytes ${start}-${end}/${size}`,'Content-Length':String(end-start+1),'Accept-Ranges':'bytes'}})}
self.addEventListener('fetch',e=>{const url=new URL(e.request.url),scope=new URL(self.registration.scope);if(url.origin!==scope.origin||!url.pathname.startsWith(scope.pathname)||e.request.method!=='GET')return;const path=url.pathname.slice(scope.pathname.length);if(path.startsWith('images/')){e.respondWith((async()=>{const cache=await caches.open(IMAGES),saved=await cache.match(url.href);if(saved)return saved;const response=await fetch(e.request);if(e.request.cache!=='reload'&&response.ok&&response.headers.get('content-type')?.startsWith('image/'))try{await cache.put(url.href,response.clone())}catch{};return response})());return}if(path.startsWith('audio/')){e.respondWith((async()=>{const cache=await caches.open(AUDIO),saved=await cache.match(url.href);if(saved)return partial(e.request,saved);return fetch(e.request)})());return}if(e.request.mode==='navigate'){e.respondWith((async()=>{try{return await fetch(e.request)}catch{return (await caches.open(CORE)).match('./index.html')}})());return}if(FILES.some(f=>new URL(f,self.registration.scope).href===url.href))e.respondWith((async()=>{const cached=await (await caches.open(CORE)).match(e.request);return cached||fetch(e.request)})())});

self.addEventListener('message',e=>{if(e.data==='ITALIA_UI_VERSION')e.ports[0]?.postMessage('offline-v5');if(e.data==='ITALIA_CACHE_CORE')e.waitUntil((async()=>{try{const cache=await caches.open(CORE);for(const file of FILES){const saved=await cache.match(file);if(saved?.ok)continue;const response=await fetch(new URL(file,self.registration.scope),{cache:'reload'});if(!response.ok)throw Error('core');await cache.put(file,response)}e.ports[0]?.postMessage({ok:true})}catch{e.ports[0]?.postMessage({ok:false})}})())});
